import XCTest
@testable import PlazaCore

final class WindowsCompatibilityTests: XCTestCase {
    func testWindowsWireNoteDecodesAndMatchesMacSteamGame() throws {
        // Generated by Windows/src/core.cjs wireNote with the shipping defaults.
        let json = #"""
        {
          "id": "fabd9065-1a49-4de9-a87c-aa5ed6e06e57",
          "author": {
            "id": "c9b10dd5-7ade-425b-81d8-7b528c533142",
            "name": "Windows Friend",
            "skin": 0,
            "hair": 33,
            "hairColor": 1,
            "eyes": 2,
            "brows": 0,
            "nose": 1,
            "mouth": 23,
            "face": 0,
            "outfit": 0,
            "glasses": false,
            "beard": false,
            "eyeSpacing": 0.16666666666666666,
            "featureHeight": 0.5,
            "height": 0.5,
            "build": 0.5,
            "features": {
              "eyeColor": 0,
              "browColor": 1,
              "mouthColor": 0,
              "glassesType": 1,
              "glassesColor": 0,
              "mustache": 0,
              "beardType": 1,
              "facialHairColor": 1,
              "wrinkles": 0,
              "makeup": 0,
              "gender": 0,
              "mole": false,
              "flipHair": false,
              "birthMonth": 0,
              "birthDay": 0,
              "favorite": false,
              "creator": "",
              "allowCopying": true,
              "sharing": true,
              "eyeSize": 0.5,
              "eyeStretch": 0.5,
              "eyeRotation": 0.5,
              "eyeY": 0.6666666666666666,
              "browSize": 0.5,
              "browStretch": 0.5,
              "browRotation": 0.5,
              "browSpacing": 0.5,
              "browY": 0.4666666666666667,
              "noseSize": 0.5,
              "noseY": 0.5,
              "mouthSize": 0.5,
              "mouthStretch": 0.5,
              "mouthY": 0.7222222222222222,
              "glassesSize": 0.5,
              "glassesY": 0.5,
              "mustacheSize": 0.5,
              "mustacheY": 0.5,
              "moleSize": 0.5,
              "moleX": 0.5,
              "moleY": 0.5
            }
          },
          "text": "Hello Mac, from Windows! 👋",
          "drawing": [
            {
              "points": [
                {
                  "x": 0.25,
                  "y": 0.3
                },
                {
                  "x": 0.7,
                  "y": 0.6
                }
              ],
              "eraser": false
            }
          ],
          "drawingDescription": "A wave from Windows",
          "created": 1791917000,
          "topic": {
            "label": "Portal 2",
            "bundleID": "steam.app.620",
            "steamAppID": 620
          }
        }
        """#
        let shared = try JSONDecoder().decode(SharedJournalNote.self, from: Data(json.utf8))
        try shared.validate()
        XCTAssertEqual(shared.author.name, "Windows Friend")
        XCTAssertEqual(shared.text, "Hello Mac, from Windows! 👋")
        XCTAssertEqual(shared.drawing.first?.points.count, 2)
        XCTAssertEqual(shared.author.features.creator, "")
        var game = AppIsland(label: "Portal 2 on Mac", bundleID: "com.valvesoftware.portal2")
        game.steamAppID = 620
        XCTAssertEqual(shared.topic?.match(in: [game])?.id, game.id)
        let local = shared.localNote(apps: [game])
        XCTAssertEqual(local.appID, game.id)
        XCTAssertEqual(local.drawingDescription, "A wave from Windows")
        XCTAssertTrue(local.shared == true)
        let roundTrip = try JSONDecoder().decode(SharedJournalNote.self, from: JSONEncoder().encode(shared))
        XCTAssertEqual(roundTrip, shared)
    }
}
